// stlport
// Shard for SlideFromRight::initReverseAnimateWindow: retail 0x005C50A8 is a
// framed /O1 prologue-save body like the Spiral family; the home TU builds
// this family under /G7 and emits a different shape so this body lives here.
// Donor-verbatim ZH initReverse; getVel is out-of-line via the rowed pin,
// setVel/setStartTime/setFinished inline to stores like the update side.
#include "PreRTS.h"
#include "GameClient/ProcessAnimateWindow.h"
#include "GameClient/AnimateWindowManager.h"
#include "GameClient/GameWindow.h"
#include "GameClient/Display.h"

// ?initReverseAnimateWindow@ProcessAnimateWindowSlideFromRight@@UAEXPAVAnimateWindow@@I@Z @0x005C50A8
void ProcessAnimateWindowSlideFromRight::initReverseAnimateWindow( AnimateWindow *animWin, UnsignedInt maxDelay )
{
	if(!animWin)
	{
		DEBUG_ASSERTCRASH( animWin, ("animWin was passed into initAnimateWindow as a NULL Pointer... bad bad bad!"));
		return;
	}
	if(animWin->getDelay() > 0)
		animWin->setStartTime(timeGetTime() + (maxDelay - animWin->getDelay()));
	Coord2D vel = animWin->getVel();
	vel.x *= -1;
	vel.y *= -1;
	animWin->setVel( vel );
	animWin->setFinished( FALSE );

}
